const fs=require('fs'),assert=require('assert'),vm=require('vm'),png=require('./scripts/png.cjs');global.window=global;vm.runInThisContext(fs.readFileSync('js/core.js','utf8'));const dir='备份/20261102-idle-side-sync/',raw=fs.readFileSync(dir+'before.json','utf8'),p=JSON.parse(raw),old=JSON.parse(fs.readFileSync(process.env.TEMP+'/idle-inspect.json','utf8').replace(/^\uFEFF/,''));const dec=c=>png.decode(Buffer.from(c.dataURL.split(',')[1],'base64'));const l=p.layers[11],a=dec(old.layers[11].frameData['8_0_2']),b=dec(l.frameData['8_0_2']),diff=[];for(let i=0;i<b.data.length;i+=4)if([0,1,2,3].some(k=>a.data[i+k]!==b.data[i+k]))diff.push({x:i/4%b.width,y:Math.floor(i/4/b.width),before:[...a.data.subarray(i,i+4)],after:[...b.data.subarray(i,i+4)]});assert.equal(diff.length,21);for(const f of [0,1,3]){const key='8_0_'+f,c=l.frameData[key],im=dec(c),dy=f<2?-2:0;for(let y=0;y<=14;y++)for(let x=0;x<=8;x++){const tx=x-(c.placement?.x||0),ty=y+dy-(c.placement?.y||0);if(tx<0||ty<0||tx>=im.width||ty>=im.height)continue;im.data.set(b.data.subarray((y*b.width+x)*4,(y*b.width+x)*4+4),(ty*im.width+tx)*4);}c.dataURL='data:image/png;base64,'+png.encode(im.width,im.height,im.data).toString('base64');}let restored=structuredClone(p);for(const f of [0,1,3])restored.layers[11].frameData['8_0_'+f]=JSON.parse(raw).layers[11].frameData['8_0_'+f];assert.deepEqual(restored,JSON.parse(raw));fs.writeFileSync(dir+'candidate.json',JSON.stringify(p));fs.writeFileSync(dir+'diff.json',JSON.stringify({layer:11,frames:[1,2,4],pixelsPerFrame:21,referenceFrame:3,diff},null,2));for(const bg of [[221,213,237,255],[35,35,45,255]]){const S=8,W=31,H=36,out=new Uint8Array(W*4*S*H*S*4);for(let f=0;f<4;f++){const data=new Uint8Array(W*H*4);for(const layer of PE.getRenderLayers(p,8,0)){if(!PE.isLayerVisible(p,layer,8))continue;const cel=layer.frameData?.['8_0_'+f];if(!cel)continue;const im=dec(cel);for(let y=0;y<im.height;y++)for(let x=0;x<im.width;x++){const tx=x+(cel.placement?.x||0),ty=y+(cel.placement?.y||0),i=(y*im.width+x)*4;if(tx>=0&&ty>=0&&tx<W&&ty<H&&im.data[i+3])data.set(im.data.subarray(i,i+4),(ty*W+tx)*4);}}assert(data.some((v,i)=>i%4===3&&v));for(let y=0;y<H*S;y++)for(let x=0;x<W*S;x++){let j=(Math.floor(y/S)*W+Math.floor(x/S))*4;out.set(data[j+3]?data.subarray(j,j+4):bg,(y*W*4*S+f*W*S+x)*4);}}fs.writeFileSync(dir+'preview-'+bg[0]+'.png',png.encode(W*4*S,H*S,out));}console.log('PASS: 63 pixels changed across frames 1,2,4; frame3 and all other fields unchanged; restoration verified');


